pub fn check_core_cast<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, inner: &Expr, ty: &Type, span: &Span) -> Ty {
    let from = check_core_expr(state, world, host, inner, span);
    let into = host.declared(state, ty, span);
    state.a_cast_over_a_lent_binding(world, inner, span);
    match into {
        Ty::Named { ref name, .. } => { if !check_core_places_offered(name) { state.cast_names_a_foreign_type(name, span); } },
        _ => { },
    }
    let into_f32 = match into {
        Ty::Named { ref name, ref args, .. } => name == "f32" && args.is_empty(),
        _ => false,
    };
    if into_f32 && check_floats_written(inner) {
        state.floats_beyond_f32(inner, &into, span);
        let added = state.flow.widening_casts.insert(id_of(inner) as i64);
    } else if !(from.is_unknown() && state.open_number_cast(world, inner, &into)) { state.record_cast(&from, &into, id_of(inner) as i64); }
    let from_a_char = match from {
        Ty::Named { ref name, .. } => name == "char" || name == "scalar",
        _ => false,
    };
    let into_an_integer = match into {
        Ty::Named { ref name, .. } => check_core_places_an_integer(name),
        _ => false,
    };
    if from_a_char && into_an_integer { state.facts.char_codes.insert(id_of(inner) as i64); }
    into
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_core_range<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, start: &Expr, end: &Expr, span: &Span) -> Ty {
    let from = check_core_expr(state, world, host, start, span);
    let to = check_core_expr(state, world, host, end, span);
    let mut item: Ty = from;
    if item.is_unknown() { item = to; }
    Ty::Seq { item: Box::new(item), is_sync: true, pauses: false, can_throw: false, parallel: false, shape: Shape { ends: true, sized: true, replays: true } }
}

